"""SEO ladder: Intermediate, Advanced and Expert courses that follow
"Found on Google" (seo). Hands-on work happens on the same Workshop site
as the web ladder: build steps add head tags, headings, links, images and
structured data, scoped to classes these lessons introduce (.recipe-card,
.local, .faq and so on) so they never fight earlier work. Search Console
and forecasting math use numeric steps; briefs, robots files, redirect
maps and strategy memos use write steps. Numbers in prompts are labeled
examples, not industry statistics.
Rebuild with: python3 build_library.py
"""
from ladder_kit import (C, W, M, O, B, L, N, X, WR, course, has, count, attr, css, html, none, rx,
                        confirm, at_most, text_max, words, must, avoid, max_sentence, lines, changed,
                        self_check)

KW = ["seo", "search", "google", "ranking"]


def ld(sel, keys, label, type_=None, hint=None):
    """Every JSON-LD block parses and has the listed top level keys."""
    c = {"sel": sel, "jsonKeys": keys, "label": label}
    if type_:
        c["jsonType"] = type_
    if hint:
        c["hint"] = hint
    return c


def words_each(sel, n, label, hint=None):
    """Every match has at least n words of text."""
    c = {"sel": sel, "wordsMin": n, "label": label}
    if hint:
        c["hint"] = hint
    return c


def text_not(sel, pattern, label, hint=None):
    """Matches exist and none has text matching the pattern (case blind)."""
    c = {"sel": sel, "textNot": pattern, "label": label}
    if hint:
        c["hint"] = hint
    return c


LDSEL = "script[type=\"application/ld+json\"]"

