SI5 = L("Internal links with purpose", KW + ["internal links", "anchor text", "linking", "orphan", "breadcrumbs", "crawl"], [
    C("Links tell search engines what matters",
      "Internal links help crawlers find pages and help them understand what each page is about. The clickable words, called anchor text, are a strong hint: a link that says weeknight pasta recipes describes its target; a link that says click here describes nothing. Pages with no internal links pointing at them, called orphan pages, are easy for search engines to miss."),
    M("Which anchor text is best for a link to your herb storage guide?",
      ["Click here", "Read more", "how to store fresh herbs", "this"], 2,
      "Descriptive anchors help screen reader users scanning a list of links too. Click here makes sense only next to the sentence around it."),
    M("Your best guide is five clicks deep from the home page. What usually helps most?",
      ["Nothing, depth does not matter", "Link to it from relevant, well linked pages such as the home page or a topic hub", "Add more keywords to it", "Put it in the sitemap only"], 1,
      "Important pages should be a few clicks from the home page, linked from pages that already earn attention."),
    B("Add a related reading block. Create an aside with class related containing at least three links. Every link in it must have descriptive anchor text of three or more words, and none may say click here, read more or here.",
      "<aside class=\"related\">\n  <h2>Keep reading</h2>\n  <a href=\"herbs.html\">How to store fresh herbs</a>\n  <a href=\"pasta.html\">Weeknight pasta in 20 minutes</a>\n  <a href=\"prep.html\">Meal prep for a busy week</a>\n</aside>",
      "Every link now says where it goes. Crawlers learn what the target is about and people can decide before they click.",
      [count(".related a[href]", 3, "At least three links in .related"),
       words_each(".related a", 3, "Every link in .related has an anchor of three or more words",
                  hint="Short anchors like Pasta tell less than Weeknight pasta in 20 minutes."),
       text_not(".related a", "^(click here|read more|here|more|this|link)$", "No link says click here, read more, here or this",
                hint="Replace vague anchors with the topic of the page the link goes to.")]),
    O("Fix an orphan page, in order.",
      ["Find pages that no other page links to", "Decide whether each one deserves to exist", "Link the keepers from relevant pages with descriptive anchors", "Redirect or remove the rest"],
      "Not every orphan should be saved. Some are outdated and are better merged or removed."),
    C("Links are for readers first",
      "Add a link where a reader would genuinely want to go next. Links stuffed into footers with exact match anchors help nobody and can look manipulative."),
])

