SI8 = L("Reading Search Console", KW + ["search console", "impressions", "clicks", "ctr", "position", "queries", "reports"], [
    C("The four numbers",
      "Search Console's Performance report shows clicks, impressions (how often your page appeared in results), click-through rate (clicks divided by impressions) and average position. Average position is an average over every time you appeared, so a page that ranks 3 for one query and 40 for another can show something in between that matches neither."),
    N("Example numbers: a query shows 250 clicks from 10,000 impressions. What is the CTR in percent?", 2.5,
      "250 divided by 10,000 is 0.025, which is 2.5%.",
      gen={"vars": {"c": [100, 600, 50], "i": [5000, 20000, 1000]}, "answer": "c/i*100", "round": 2,
           "prompt": "Example numbers: a query shows {c} clicks from {i} impressions. What is the CTR in percent?",
           "explain": "{c} divided by {i}, times 100, is {A}%."}),
    M("A page has many impressions, an average position around 4, and a low CTR. What is the first thing to try?",
      ["Build more links", "Rewrite the title and description so the snippet matches the query better", "Delete the page", "Change the URL"], 1,
      "It already ranks well enough to be seen. People see it and choose something else, which points to the snippet."),
    M("Impressions doubled this month but clicks stayed flat. Which explanation is possible and worth checking first?",
      ["Google is broken", "The page started appearing for new queries where it ranks low, so many people see it but few scroll that far", "The CTR formula changed", "The site was penalized"], 1,
      "Open the queries for that page and sort by impressions. New low ranking queries add impressions without clicks."),
    O("Investigate a traffic drop, in order.",
      ["Confirm the drop and its dates in the Performance report", "Compare the period with the same one before it to find which pages and queries fell", "Check for site changes, indexing problems or manual actions around those dates", "Fix the cause you found, then annotate the date and watch the trend"],
      "Narrow first, then explain. Guessing at causes before you know which pages fell leads to fixing the wrong thing."),
    W("Find the quick wins",
      "Example data: Page A ranks at an average position of 8 for a query with 5,000 impressions. Page B ranks at 45 for a query with 9,000 impressions. Which do you work on first?",
      ["Page A is already near the top of page one. Small improvements can move it into positions where many more people click.",
       "Page B is far from page one. It needs much bigger work before more people see it.",
       "So Page A is the quick win: improve its content and snippet for that query.",
       "Page B goes on the list for deeper work later."],
      "Positions roughly 5 to 15 are often where small improvements pay off fastest."),
    C("Search Console data is sampled and delayed",
      "Numbers arrive a few days late and some rare queries are hidden for privacy. Use it for trends and direction rather than precise totals."),
])

